window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b4b135ebe3bef338"]={"versions": [{"id": "FIG-b4b135ebe3bef338", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).</li>\n<li><strong>Technischer Zweck:</strong> Visualisierung des Kontrollflusses und Interaktionsvertrags zwischen externem Diagnosetester (Generic Scan Tool), dem AUTOSAR-Kommunikationsmodul [<code>Dcm</code>](file:///private/tmp/autodocs-worktrees/task-figure-evidence) (Diagnostic Communication Manager) und dem Fehlerspeichermodul [<code>Dem</code>](file:///private/tmp/autodocs-worktrees/task-figure-evidence) (Diagnostic Event Manager).</li>\n<li><strong>Funktionale Einordnung:</strong> UDS-Diagnoseservice <code>0x19</code> (<em>ReadDTCInformation</em>) nach ISO 14229-1 innerhalb der AUTOSAR Classic Platform (Services Layer, BSW). Das Diagramm spezifiziert die Verarbeitung zeitbezogener DTC-Abfragen (chronologische Selektion nach Auftrittszeitpunkt).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & BSW-Module:</strong></li>\n<li><code>Generic Scan Tool</code>: Externer Diagnosetester / UDS-Client.</li>\n<li><code>«module» Dcm</code>: BSW-Modul (ISO 14229-1 Service Handler / DSP-Submodul). Trägt das UML-Symbol für Komponenten/Klassen mit interner Struktur/Ports.</li>\n<li><code>«module» Dem</code>: BSW-Modul; Host des Fault Memorys, verantwortlich für DTC-Status, Event-Chronologie und Freeze-Frames.</li>\n<li><strong>Schnittstellen & Datentypen:</strong></li>\n<li><strong>UDS Diagnostic Request:</strong> Service <code>0x19</code> (<em>ReadDTCInformation</em>) mit den ISO-14229-1 Subfunktionen:</li>\n<li><code>0x0B</code>: <code>reportFirstTestFailedDTC</code></li>\n<li><code>0x0C</code>: <code>reportFirstConfirmedDTC</code></li>\n<li><code>0x0D</code>: <code>reportMostRecentTestFailedDTC</code></li>\n<li><code>0x0E</code>: <code>reportMostRecentConfirmedDTC</code></li>\n<li><strong>BSW-API:</strong> [<code>Dem_DcmGetDTCByOccurrenceTime(...)</code>](file:///private/tmp/autodocs-worktrees/task-figure-evidence)</li>\n<li><code>Dem_ReturnGetDTCByOccurrenceTimeType</code> (Rückgabetyp, z. B. <code>DEM_OCCURR_OK</code>, <code>DEM_OCCURR_NOT_AVAILABLE</code>): Signalisiert Erfolg oder Nichtverfügbarkeit eines passenden DTCs.</li>\n<li><code>DTCRequestType</code> / <code>Dem_DTCRequestType</code> (In-Parameter): Definiert das zeitliche Filterkriterium (First/Most Recent, Failed/Confirmed).</li>\n<li><code>uint32* DTC</code> (Out-Parameter): Zeiger auf den 3-Byte-DTC-Wert (UDS-Format, High-Byte bis Low-Byte).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Das <code>Generic Scan Tool</code> sendet einen Diagnoserequest <code>ReadDTCInformation</code> (Service <code>0x19</code>) mit einer der zeitbasierten Subfunktionen (<code>0x0B</code>–<code>0x0E</code>) an die ECU (über PduR/CanTp/DoIP an den <code>Dcm</code>).</li>\n<li><strong>Synchroner Modulaufruf:</strong> Der <code>Dcm</code> parst die Subfunktion, mappt sie auf den Aufrufparameter <code>Dem_DTCRequestType</code> und ruft synchron die BSW-C-API [<code>Dem_DcmGetDTCByOccurrenceTime</code>](file:///private/tmp/autodocs-worktrees/task-figure-evidence) auf.</li>\n<li><strong>Auswertung im Dem:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>Dem</code> ermittelt im internen Event-Memory anhand der chronologischen Zeitstempel/Reihenfolge den geforderten DTC.</li>\n<li>Der <code>Dem</code> liefert synchron den Rückgabewert (<code>Dem_ReturnGetDTCByOccurrenceTimeType</code>) und belegt im Erfolgsfall den Out-Parameter <code>DTC</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Antwortgenerierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Positiver Pfad:</strong> Gibt der <code>Dem</code> <code>DEM_OCCURR_OK</code> zurück, serialisiert der <code>Dcm</code> die positive Response <code>0x59 &lt;SubFunction&gt; &lt;DTCStatusAvailabilityMask&gt; &lt;DTCAndStatusRecord&gt;</code> und sendet sie an den Tester.</li>\n<li><strong>Negativer Pfad:</strong> Liefert der <code>Dem</code> <code>DEM_OCCURR_NOT_AVAILABLE</code> oder schlägt die Validierung fehl (z. B. falsches Subfunktionsformat), erzeugt der <code>Dcm</code> eine negative Response (NRC, z. B. NRC <code>0x31</code> <em>Request Out Of Range</em> oder NRC <code>0x12</code> <em>SubFunctionNotSupported</em>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsabhängigkeit:</strong></li>\n<li>Das Feature erfordert im <code>Dem</code> die Aktivierung der chronologischen Event-Speicherung (Parameter <code>DemOccurrenceCounterProcessing</code> bzw. chronologisches FIFO/Ringpuffer-Management für Event-Records).</li>\n<li>Im <code>Dcm</code> müssen die Subfunktionen <code>0x0B</code>–<code>0x0E</code> in <code>DcmDspReadDTC</code> explizit konfiguriert und aktiviert sein (<code>DcmDspReadDtcByOccurrenceTimeSupported = TRUE</code>).</li>\n<li><strong>API-Vertrag (Synchronität):</strong></li>\n<li>[<code>Dem_DcmGetDTCByOccurrenceTime</code>](file:///private/tmp/autodocs-worktrees/task-figure-evidence) ist eine <strong>synchrone</strong> API. Der <code>Dem</code> muss die Information direkt ohne Blockieren oder Kontextwechsel aus dem RAM liefern. Eine Verzögerung blockiert die Task des <code>Dcm</code> (<code>Dcm_MainFunction</code>).</li>\n<li><strong>Format-Mapping:</strong></li>\n<li>Der Out-Parameter liefert den 24-Bit-DTC in einem <code>uint32</code>. Entwickler müssen sicherstellen, dass das High-Byte im <code>uint32</code> normgerecht auf 0 bzw. das geforderte UDS-Format maskiert ist, bevor der <code>Dcm</code> das PDU-Payload assembliert.</li>\n</ul>"}, {"id": "FIG-ef0fb62f266adb57", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).</li>\n<li><strong>Technischer Zweck:</strong> Visualisierung des Kontrollflusses und Interaktionsvertrags zwischen externem Diagnosetester (Generic Scan Tool), dem AUTOSAR-Kommunikationsmodul [<code>Dcm</code>](file:///private/tmp/autodocs-worktrees/task-figure-evidence) (Diagnostic Communication Manager) und dem Fehlerspeichermodul [<code>Dem</code>](file:///private/tmp/autodocs-worktrees/task-figure-evidence) (Diagnostic Event Manager).</li>\n<li><strong>Funktionale Einordnung:</strong> UDS-Diagnoseservice <code>0x19</code> (<em>ReadDTCInformation</em>) nach ISO 14229-1 innerhalb der AUTOSAR Classic Platform (Services Layer, BSW). Das Diagramm spezifiziert die Verarbeitung zeitbezogener DTC-Abfragen (chronologische Selektion nach Auftrittszeitpunkt).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & BSW-Module:</strong></li>\n<li><code>Generic Scan Tool</code>: Externer Diagnosetester / UDS-Client.</li>\n<li><code>«module» Dcm</code>: BSW-Modul (ISO 14229-1 Service Handler / DSP-Submodul). Trägt das UML-Symbol für Komponenten/Klassen mit interner Struktur/Ports.</li>\n<li><code>«module» Dem</code>: BSW-Modul; Host des Fault Memorys, verantwortlich für DTC-Status, Event-Chronologie und Freeze-Frames.</li>\n<li><strong>Schnittstellen & Datentypen:</strong></li>\n<li><strong>UDS Diagnostic Request:</strong> Service <code>0x19</code> (<em>ReadDTCInformation</em>) mit den ISO-14229-1 Subfunktionen:</li>\n<li><code>0x0B</code>: <code>reportFirstTestFailedDTC</code></li>\n<li><code>0x0C</code>: <code>reportFirstConfirmedDTC</code></li>\n<li><code>0x0D</code>: <code>reportMostRecentTestFailedDTC</code></li>\n<li><code>0x0E</code>: <code>reportMostRecentConfirmedDTC</code></li>\n<li><strong>BSW-API:</strong> [<code>Dem_DcmGetDTCByOccurrenceTime(...)</code>](file:///private/tmp/autodocs-worktrees/task-figure-evidence)</li>\n<li><code>Dem_ReturnGetDTCByOccurrenceTimeType</code> (Rückgabetyp, z. B. <code>DEM_OCCURR_OK</code>, <code>DEM_OCCURR_NOT_AVAILABLE</code>): Signalisiert Erfolg oder Nichtverfügbarkeit eines passenden DTCs.</li>\n<li><code>Dem_DTCRequestType</code> (In-Parameter): Definiert das zeitliche Filterkriterium (First/Most Recent, Failed/Confirmed).</li>\n<li><code>uint32* DTC</code> (Out-Parameter): Zeiger auf den 3-Byte-DTC-Wert (UDS-Format, High-Byte bis Low-Byte).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Das <code>Generic Scan Tool</code> sendet einen Diagnoserequest <code>ReadDTCInformation</code> (Service <code>0x19</code>) mit einer der zeitbasierten Subfunktionen (<code>0x0B</code>–<code>0x0E</code>) an die ECU (über PduR/CanTp/DoIP an den <code>Dcm</code>).</li>\n<li><strong>Synchroner Modulaufruf:</strong> Der <code>Dcm</code> parst die Subfunktion, mappt sie auf den Aufrufparameter <code>Dem_DTCRequestType</code> und ruft synchron die BSW-C-API [<code>Dem_DcmGetDTCByOccurrenceTime</code>](file:///private/tmp/autodocs-worktrees/task-figure-evidence) auf.</li>\n<li><strong>Auswertung im Dem:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>Dem</code> ermittelt im internen Event-Memory anhand der chronologischen Zeitstempel/Reihenfolge den geforderten DTC.</li>\n<li>Der <code>Dem</code> liefert synchron den Rückgabewert (<code>Dem_ReturnGetDTCByOccurrenceTimeType</code>) und belegt im Erfolgsfall den Out-Parameter <code>DTC</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Antwortgenerierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Positiver Pfad:</strong> Gibt der <code>Dem</code> <code>DEM_OCCURR_OK</code> zurück, serialisiert der <code>Dcm</code> die positive Response <code>0x59 &lt;SubFunction&gt; &lt;DTCStatusAvailabilityMask&gt; &lt;DTCAndStatusRecord&gt;</code> und sendet sie an den Tester.</li>\n<li><strong>Negativer Pfad:</strong> Liefert der <code>Dem</code> <code>DEM_OCCURR_NOT_AVAILABLE</code> oder schlägt die Validierung fehl (z. B. falsches Subfunktionsformat), erzeugt der <code>Dcm</code> eine negative Response (NRC, z. B. NRC <code>0x31</code> <em>Request Out Of Range</em> oder NRC <code>0x12</code> <em>SubFunctionNotSupported</em>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsabhängigkeit:</strong></li>\n<li>Das Feature erfordert im <code>Dem</code> die Aktivierung der chronologischen Event-Speicherung (Parameter <code>DemOccurrenceCounterProcessing</code> bzw. chronologisches FIFO/Ringpuffer-Management für Event-Records).</li>\n<li>Im <code>Dcm</code> müssen die Subfunktionen <code>0x0B</code>–<code>0x0E</code> in <code>DcmDspReadDTC</code> explizit konfiguriert und aktiviert sein (<code>DcmDspReadDtcByOccurrenceTimeSupported = TRUE</code>).</li>\n<li><strong>API-Vertrag (Synchronität):</strong></li>\n<li>[<code>Dem_DcmGetDTCByOccurrenceTime</code>](file:///private/tmp/autodocs-worktrees/task-figure-evidence) ist eine <strong>synchrone</strong> API. Der <code>Dem</code> muss die Information direkt ohne Blockieren oder Kontextwechsel aus dem RAM liefern. Eine Verzögerung blockiert die Task des <code>Dcm</code> (<code>Dcm_MainFunction</code>).</li>\n<li><strong>Format-Mapping:</strong></li>\n<li>Der Out-Parameter liefert den 24-Bit-DTC in einem <code>uint32</code>. Entwickler müssen sicherstellen, dass das High-Byte im <code>uint32</code> normgerecht auf 0 bzw. das geforderte UDS-Format maskiert ist, bevor der <code>Dcm</code> das PDU-Payload assembliert.</li>\n</ul>"}, {"id": "FIG-a46f9d14591d42b6", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).</li>\n<li><strong>Technischer Zweck:</strong> Visualisierung des Kontrollflusses und Interaktionsvertrags zwischen externem Diagnosetester (Generic Scan Tool), dem AUTOSAR-Kommunikationsmodul [<code>Dcm</code>](file:///private/tmp/autodocs-worktrees/task-figure-evidence) (Diagnostic Communication Manager) und dem Fehlerspeichermodul [<code>Dem</code>](file:///private/tmp/autodocs-worktrees/task-figure-evidence) (Diagnostic Event Manager).</li>\n<li><strong>Funktionale Einordnung:</strong> UDS-Diagnoseservice <code>0x19</code> (<em>ReadDTCInformation</em>) nach ISO 14229-1 innerhalb der AUTOSAR Classic Platform (Services Layer, BSW). Das Diagramm spezifiziert die Verarbeitung zeitbezogener DTC-Abfragen (chronologische Selektion nach Auftrittszeitpunkt).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & BSW-Module:</strong></li>\n<li><code>Generic Scan Tool</code>: Externer Diagnosetester / UDS-Client.</li>\n<li><code>«module» Dcm</code>: BSW-Modul (ISO 14229-1 Service Handler / DSP-Submodul). Trägt das UML-Symbol für Komponenten/Klassen mit interner Struktur/Ports.</li>\n<li><code>«module» Dem</code>: BSW-Modul; Host des Fault Memorys, verantwortlich für DTC-Status, Event-Chronologie und Freeze-Frames.</li>\n<li><strong>Schnittstellen & Datentypen:</strong></li>\n<li><strong>UDS Diagnostic Request:</strong> Service <code>0x19</code> (<em>ReadDTCInformation</em>) mit den ISO-14229-1 Subfunktionen:</li>\n<li><code>0x0B</code>: <code>reportFirstTestFailedDTC</code></li>\n<li><code>0x0C</code>: <code>reportFirstConfirmedDTC</code></li>\n<li><code>0x0D</code>: <code>reportMostRecentTestFailedDTC</code></li>\n<li><code>0x0E</code>: <code>reportMostRecentConfirmedDTC</code></li>\n<li><strong>BSW-API:</strong> [<code>Dem_GetDTCByOccurrenceTime(...)</code>](file:///private/tmp/autodocs-worktrees/task-figure-evidence)</li>\n<li><code>Std_ReturnType</code> (Rückgabetyp, z. B. <code>E_OK</code>, <code>DEM_OCCURR_NOT_AVAILABLE</code> / <code>E_NOT_OK</code>): Signalisiert Erfolg oder Nichtverfügbarkeit eines passenden DTCs.</li>\n<li><code>uint8 ClientId</code> (In-Parameter): Kennung des anfordernden Dcm-Clients.</li>\n<li><code>Dem_DTCRequestType</code> (In-Parameter): Definiert das zeitliche Filterkriterium (First/Most Recent, Failed/Confirmed).</li>\n<li><code>uint32* DTC</code> (Out-Parameter): Zeiger auf den 3-Byte-DTC-Wert (UDS-Format, High-Byte bis Low-Byte).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Das <code>Generic Scan Tool</code> sendet einen Diagnoserequest <code>ReadDTCInformation</code> (Service <code>0x19</code>) mit einer der zeitbasierten Subfunktionen (<code>0x0B</code>–<code>0x0E</code>) an die ECU (über PduR/CanTp/DoIP an den <code>Dcm</code>).</li>\n<li><strong>Synchroner Modulaufruf:</strong> Der <code>Dcm</code> parst die Subfunktion, mappt sie auf den Aufrufparameter <code>Dem_DTCRequestType</code> und ruft synchron die BSW-C-API [<code>Dem_GetDTCByOccurrenceTime</code>](file:///private/tmp/autodocs-worktrees/task-figure-evidence) unter Übergabe der <code>ClientId</code> auf.</li>\n<li><strong>Auswertung im Dem:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>Dem</code> ermittelt im internen Event-Memory anhand der chronologischen Zeitstempel/Reihenfolge den geforderten DTC.</li>\n<li>Der <code>Dem</code> liefert synchron den Rückgabewert (<code>Std_ReturnType</code>) und belegt im Erfolgsfall den Out-Parameter <code>DTC</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Antwortgenerierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Positiver Pfad:</strong> Gibt der <code>Dem</code> <code>E_OK</code> zurück, serialisiert der <code>Dcm</code> die positive Response <code>0x59 &lt;SubFunction&gt; &lt;DTCStatusAvailabilityMask&gt; &lt;DTCAndStatusRecord&gt;</code> und sendet sie an den Tester.</li>\n<li><strong>Negativer Pfad:</strong> Liefert der <code>Dem</code> <code>DEM_OCCURR_NOT_AVAILABLE</code> (oder einen Fehlercode ungleich <code>E_OK</code>) oder schlägt die Validierung fehl, erzeugt der <code>Dcm</code> eine negative Response (NRC, z. B. NRC <code>0x31</code> <em>Request Out Of Range</em> oder NRC <code>0x12</code> <em>SubFunctionNotSupported</em>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsabhängigkeit:</strong></li>\n<li>Das Feature erfordert im <code>Dem</code> die Aktivierung der chronologischen Event-Speicherung (Parameter <code>DemOccurrenceCounterProcessing</code> bzw. chronologisches FIFO/Ringpuffer-Management für Event-Records).</li>\n<li>Im <code>Dcm</code> müssen die Subfunktionen <code>0x0B</code>–<code>0x0E</code> in <code>DcmDspReadDTC</code> explizit konfiguriert und aktiviert sein (<code>DcmDspReadDtcByOccurrenceTimeSupported = TRUE</code>).</li>\n<li><strong>API-Vertrag (Synchronität & Client-Identifikation):</strong></li>\n<li>[<code>Dem_GetDTCByOccurrenceTime</code>](file:///private/tmp/autodocs-worktrees/task-figure-evidence) ist eine <strong>synchrone</strong> API. Der <code>Dem</code> muss die Information direkt ohne Blockieren oder Kontextwechsel aus dem RAM liefern. Eine Verzögerung blockiert die Task des <code>Dcm</code> (<code>Dcm_MainFunction</code>).</li>\n<li>Über den Parameter <code>ClientId</code> (<code>uint8</code>) adressiert der <code>Dcm</code> die dedizierte Client-Instanz im <code>Dem</code>, um parallele Diagnosezugriffe sauber zu trennen.</li>\n<li><strong>Format-Mapping:</strong></li>\n<li>Der Out-Parameter liefert den 24-Bit-DTC in einem <code>uint32</code>. Entwickler müssen sicherstellen, dass das High-Byte im <code>uint32</code> normgerecht auf 0 bzw. das geforderte UDS-Format maskiert ist, bevor der <code>Dcm</code> das PDU-Payload assembliert.</li>\n</ul>"}, {"id": "FIG-34beeef76e65957d", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).</li>\n<li><strong>Technischer Zweck:</strong> Visualisierung des Kontrollflusses und Interaktionsvertrags zwischen externem Diagnosetester (Generic Scan Tool), dem AUTOSAR-Kommunikationsmodul [<code>Dcm</code>](file:///private/tmp/autodocs-worktrees/task-figure-evidence) (Diagnostic Communication Manager) und dem Fehlerspeichermodul [<code>Dem</code>](file:///private/tmp/autodocs-worktrees/task-figure-evidence) (Diagnostic Event Manager).</li>\n<li><strong>Funktionale Einordnung:</strong> UDS-Diagnoseservice <code>0x19</code> (<em>ReadDTCInformation</em>) nach ISO 14229-1 innerhalb der AUTOSAR Classic Platform (Services Layer, BSW). Das Diagramm spezifiziert die Verarbeitung zeitbezogener DTC-Abfragen (chronologische Selektion nach Auftrittszeitpunkt).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & BSW-Module:</strong></li>\n<li><code>Generic Scan Tool</code>: Externer Diagnosetester / UDS-Client.</li>\n<li><code>«module» Dcm</code>: BSW-Modul (ISO 14229-1 Service Handler / DSP-Submodul). Trägt das UML-Symbol für Komponenten/Klassen mit interner Struktur/Ports.</li>\n<li><code>«module» Dem</code>: BSW-Modul; Host des Fault Memorys, verantwortlich für DTC-Status, Event-Chronologie und Freeze-Frames.</li>\n<li><strong>Schnittstellen & Datentypen:</strong></li>\n<li><strong>UDS Diagnostic Request:</strong> Service <code>0x19</code> (<em>ReadDTCInformation</em>) mit den ISO-14229-1 Subfunktionen:</li>\n<li><code>0x0B</code>: <code>reportFirstTestFailedDTC</code></li>\n<li><code>0x0C</code>: <code>reportFirstConfirmedDTC</code></li>\n<li><code>0x0D</code>: <code>reportMostRecentTestFailedDTC</code></li>\n<li><code>0x0E</code>: <code>reportMostRecentConfirmedDTC</code></li>\n<li><strong>BSW-API:</strong> [<code>Dem_GetDTCByOccurrenceTime(...)</code>](file:///private/tmp/autodocs-worktrees/task-figure-evidence)</li>\n<li><code>Std_ReturnType</code> (Rückgabetyp, z. B. <code>E_OK</code>, <code>DEM_OCCURR_NOT_AVAILABLE</code> / <code>E_NOT_OK</code>): Signalisiert Erfolg oder Nichtverfügbarkeit eines passenden DTCs.</li>\n<li><code>uint8 ClientId</code> (In-Parameter): Kennung des anfordernden Dcm-Clients.</li>\n<li><code>Dem_DTCRequestType</code> (In-Parameter): Definiert das zeitliche Filterkriterium (First/Most Recent, Failed/Confirmed).</li>\n<li><code>uint32** DTC</code> (Out-Parameter): Zeiger auf den Puffer bzw. Speicherort für den 3-Byte-DTC-Wert (UDS-Format, High-Byte bis Low-Byte).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Das <code>Generic Scan Tool</code> sendet einen Diagnoserequest <code>ReadDTCInformation</code> (Service <code>0x19</code>) mit einer der zeitbasierten Subfunktionen (<code>0x0B</code>–<code>0x0E</code>) an die ECU (über PduR/CanTp/DoIP an den <code>Dcm</code>).</li>\n<li><strong>Synchroner Modulaufruf:</strong> Der <code>Dcm</code> parst die Subfunktion, mappt sie auf den Aufrufparameter <code>Dem_DTCRequestType</code> und ruft synchron die BSW-C-API [<code>Dem_GetDTCByOccurrenceTime</code>](file:///private/tmp/autodocs-worktrees/task-figure-evidence) unter Übergabe der <code>ClientId</code> auf.</li>\n<li><strong>Auswertung im Dem:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>Dem</code> ermittelt im internen Event-Memory anhand der chronologischen Zeitstempel/Reihenfolge den geforderten DTC.</li>\n<li>Der <code>Dem</code> liefert synchron den Rückgabewert (<code>Std_ReturnType</code>) und belegt im Erfolgsfall den Out-Parameter <code>DTC</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Antwortgenerierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Positiver Pfad:</strong> Gibt der <code>Dem</code> <code>E_OK</code> zurück, serialisiert der <code>Dcm</code> die positive Response <code>0x59 &lt;SubFunction&gt; &lt;DTCStatusAvailabilityMask&gt; &lt;DTCAndStatusRecord&gt;</code> und sendet sie an den Tester.</li>\n<li><strong>Negativer Pfad:</strong> Liefert der <code>Dem</code> <code>DEM_OCCURR_NOT_AVAILABLE</code> (oder einen Fehlercode ungleich <code>E_OK</code>) oder schlägt die Validierung fehl, erzeugt der <code>Dcm</code> eine negative Response (NRC, z. B. NRC <code>0x31</code> <em>Request Out Of Range</em> oder NRC <code>0x12</code> <em>SubFunctionNotSupported</em>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsabhängigkeit:</strong></li>\n<li>Das Feature erfordert im <code>Dem</code> die Aktivierung der chronologischen Event-Speicherung (Parameter <code>DemOccurrenceCounterProcessing</code> bzw. chronologisches FIFO/Ringpuffer-Management für Event-Records).</li>\n<li>Im <code>Dcm</code> müssen die Subfunktionen <code>0x0B</code>–<code>0x0E</code> in <code>DcmDspReadDTC</code> explizit konfiguriert und aktiviert sein (<code>DcmDspReadDtcByOccurrenceTimeSupported = TRUE</code>).</li>\n<li><strong>API-Vertrag (Synchronität & Client-Identifikation):</strong></li>\n<li>[<code>Dem_GetDTCByOccurrenceTime</code>](file:///private/tmp/autodocs-worktrees/task-figure-evidence) ist eine <strong>synchrone</strong> API. Der <code>Dem</code> muss die Information direkt ohne Blockieren oder Kontextwechsel aus dem RAM liefern. Eine Verzögerung blockiert die Task des <code>Dcm</code> (<code>Dcm_MainFunction</code>).</li>\n<li>Über den Parameter <code>ClientId</code> (<code>uint8</code>) adressiert der <code>Dcm</code> die dedizierte Client-Instanz im <code>Dem</code>, um parallele Diagnosezugriffe sauber zu trennen.</li>\n<li><strong>Format-Mapping:</strong></li>\n<li>Der Out-Parameter liefert den 24-Bit-DTC in einem <code>uint32</code>. Entwickler müssen sicherstellen, dass das High-Byte im <code>uint32</code> normgerecht auf 0 bzw. das geforderte UDS-Format maskiert ist, bevor der <code>Dcm</code> das PDU-Payload assembliert.</li>\n</ul>"}, {"id": "FIG-f25e39c21e26fe62", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).</li>\n<li><strong>Technischer Zweck:</strong> Visualisierung des Kontrollflusses und Interaktionsvertrags zwischen externem Diagnosetester (Generic Scan Tool), dem AUTOSAR-Kommunikationsmodul [<code>Dcm</code>](file:///private/tmp/autodocs-worktrees/task-figure-evidence) (Diagnostic Communication Manager) und dem Fehlerspeichermodul [<code>Dem</code>](file:///private/tmp/autodocs-worktrees/task-figure-evidence) (Diagnostic Event Manager).</li>\n<li><strong>Funktionale Einordnung:</strong> UDS-Diagnoseservice <code>0x19</code> (<em>ReadDTCInformation</em>) nach ISO 14229-1 innerhalb der AUTOSAR Classic Platform (Services Layer, BSW). Das Diagramm spezifiziert die Verarbeitung zeitbezogener DTC-Abfragen (chronologische Selektion nach Auftrittszeitpunkt).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & BSW-Module:</strong></li>\n<li><code>Generic Scan Tool</code>: Externer Diagnosetester / UDS-Client.</li>\n<li><code>«module» Dcm</code>: BSW-Modul (ISO 14229-1 Service Handler / DSP-Submodul). Trägt das UML-Symbol für Komponenten/Klassen mit interner Struktur/Ports.</li>\n<li><code>«module» Dem</code>: BSW-Modul; Host des Fault Memorys, verantwortlich für DTC-Status, Event-Chronologie und Freeze-Frames.</li>\n<li><strong>Schnittstellen & Datentypen:</strong></li>\n<li><strong>UDS Diagnostic Request:</strong> Service <code>0x19</code> (<em>ReadDTCInformation</em>) mit den ISO-14229-1 Subfunktionen:</li>\n<li><code>0x0B</code>: <code>reportFirstTestFailedDTC</code></li>\n<li><code>0x0C</code>: <code>reportFirstConfirmedDTC</code></li>\n<li><code>0x0D</code>: <code>reportMostRecentTestFailedDTC</code></li>\n<li><code>0x0E</code>: <code>reportMostRecentConfirmedDTC</code></li>\n<li><strong>BSW-API:</strong> [<code>Dem_GetDTCByOccurrenceTime(...)</code>](file:///private/tmp/autodocs-worktrees/task-figure-evidence)</li>\n<li><code>Std_ReturnType</code> (Rückgabetyp, z. B. <code>E_OK</code>, <code>DEM_OCCURR_NOT_AVAILABLE</code> / <code>E_NOT_OK</code>): Signalisiert Erfolg oder Nichtverfügbarkeit eines passenden DTCs.</li>\n<li><code>uint8 ClientId</code> (In-Parameter): Kennung des anfordernden Dcm-Clients.</li>\n<li><code>Dem_DTCRequestType</code> (In-Parameter): Definiert das zeitliche Filterkriterium (First/Most Recent, Failed/Confirmed).</li>\n<li><code>uint32** DTC</code> (Out-Parameter): Zeiger auf den Puffer bzw. Speicherort für den 3-Byte-DTC-Wert (UDS-Format, High-Byte bis Low-Byte).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Das <code>Generic Scan Tool</code> sendet einen Diagnoserequest <code>ReadDTCInformation</code> (Service <code>0x19</code>) mit einer der zeitbasierten Subfunktionen (<code>0x0B</code>–<code>0x0E</code>) an die ECU (über PduR/CanTp/DoIP an den <code>Dcm</code>).</li>\n<li><strong>Synchroner Modulaufruf:</strong> Der <code>Dcm</code> parst die Subfunktion, mappt sie auf den Aufrufparameter <code>Dem_DTCRequestType</code> und ruft synchron die BSW-C-API [<code>Dem_GetDTCByOccurrenceTime</code>](file:///private/tmp/autodocs-worktrees/task-figure-evidence) unter Übergabe der <code>ClientId</code> auf.</li>\n<li><strong>Auswertung im Dem:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>Dem</code> ermittelt im internen Event-Memory anhand der chronologischen Zeitstempel/Reihenfolge den geforderten DTC.</li>\n<li>Der <code>Dem</code> liefert synchron den Rückgabewert (<code>Std_ReturnType</code>) und belegt im Erfolgsfall den Out-Parameter <code>DTC</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Antwortgenerierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Positiver Pfad:</strong> Gibt der <code>Dem</code> <code>E_OK</code> zurück, serialisiert der <code>Dcm</code> die positive Response <code>0x59 &lt;SubFunction&gt; &lt;DTCStatusAvailabilityMask&gt; &lt;DTCAndStatusRecord&gt;</code> und sendet sie an den Tester.</li>\n<li><strong>Negativer Pfad:</strong> Liefert der <code>Dem</code> <code>DEM_OCCURR_NOT_AVAILABLE</code> (oder einen Fehlercode ungleich <code>E_OK</code>) oder schlägt die Validierung fehl, erzeugt der <code>Dcm</code> eine negative Response (NRC, z. B. NRC <code>0x31</code> <em>Request Out Of Range</em> oder NRC <code>0x12</code> <em>SubFunctionNotSupported</em>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsabhängigkeit:</strong></li>\n<li>Das Feature erfordert im <code>Dem</code> die Aktivierung der chronologischen Event-Speicherung (Parameter <code>DemOccurrenceCounterProcessing</code> bzw. chronologisches FIFO/Ringpuffer-Management für Event-Records).</li>\n<li>Im <code>Dcm</code> müssen die Subfunktionen <code>0x0B</code>–<code>0x0E</code> in <code>DcmDspReadDTC</code> explizit konfiguriert und aktiviert sein (<code>DcmDspReadDtcByOccurrenceTimeSupported = TRUE</code>).</li>\n<li><strong>API-Vertrag (Synchronität & Client-Identifikation):</strong></li>\n<li>[<code>Dem_GetDTCByOccurrenceTime</code>](file:///private/tmp/autodocs-worktrees/task-figure-evidence) ist eine <strong>synchrone</strong> API. Der <code>Dem</code> muss die Information direkt ohne Blockieren oder Kontextwechsel aus dem RAM liefern. Eine Verzögerung blockiert die Task des <code>Dcm</code> (<code>Dcm_MainFunction</code>).</li>\n<li>Über den Parameter <code>ClientId</code> (<code>uint8</code>) adressiert der <code>Dcm</code> die dedizierte Client-Instanz im <code>Dem</code>, um parallele Diagnosezugriffe sauber zu trennen.</li>\n<li><strong>Format-Mapping:</strong></li>\n<li>Der Out-Parameter liefert den 24-Bit-DTC in einem <code>uint32</code>. Entwickler müssen sicherstellen, dass das High-Byte im <code>uint32</code> normgerecht auf 0 bzw. das geforderte UDS-Format maskiert ist, bevor der <code>Dcm</code> das PDU-Payload assembliert.</li>\n</ul>"}, {"id": "FIG-1f7f96e3197b1255", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).</li>\n<li><strong>Technischer Zweck:</strong> Visualisierung des Kontrollflusses und Interaktionsvertrags zwischen externem Diagnosetester (Generic Scan Tool), dem AUTOSAR-Kommunikationsmodul [<code>Dcm</code>](file:///private/tmp/autodocs-worktrees/task-figure-evidence) (Diagnostic Communication Manager) und dem Fehlerspeichermodul [<code>Dem</code>](file:///private/tmp/autodocs-worktrees/task-figure-evidence) (Diagnostic Event Manager).</li>\n<li><strong>Funktionale Einordnung:</strong> UDS-Diagnoseservice <code>0x19</code> (<em>ReadDTCInformation</em>) nach ISO 14229-1 innerhalb der AUTOSAR Classic Platform (Services Layer, BSW). Das Diagramm spezifiziert die Verarbeitung zeitbezogener DTC-Abfragen (chronologische Selektion nach Auftrittszeitpunkt).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & BSW-Module:</strong></li>\n<li><code>Generic Scan Tool</code>: Externer Diagnosetester / UDS-Client.</li>\n<li><code>«module» Dcm</code>: BSW-Modul (ISO 14229-1 Service Handler / DSP-Submodul). Trägt das UML-Symbol für Komponenten/Klassen mit interner Struktur/Ports.</li>\n<li><code>«module» Dem</code>: BSW-Modul; Host des Fault Memorys, verantwortlich für DTC-Status, Event-Chronologie und Freeze-Frames.</li>\n<li><strong>Schnittstellen & Datentypen:</strong></li>\n<li><strong>UDS Diagnostic Request:</strong> Service <code>0x19</code> (<em>ReadDTCInformation</em>) mit den ISO-14229-1 Subfunktionen:</li>\n<li><code>0x0B</code>: <code>reportFirstTestFailedDTC</code></li>\n<li><code>0x0C</code>: <code>reportFirstConfirmedDTC</code></li>\n<li><code>0x0D</code>: <code>reportMostRecentTestFailedDTC</code></li>\n<li><code>0x0E</code>: <code>reportMostRecentConfirmedDTC</code></li>\n<li><strong>BSW-API:</strong> [<code>Dem_GetDTCByOccurrenceTime(...)</code>](file:///private/tmp/autodocs-worktrees/task-figure-evidence)</li>\n<li><code>Std_ReturnType</code> (Rückgabetyp, z. B. <code>E_OK</code>, <code>DEM_OCCURR_NOT_AVAILABLE</code> / <code>E_NOT_OK</code>): Signalisiert Erfolg oder Nichtverfügbarkeit eines passenden DTCs.</li>\n<li><code>uint8 ClientId</code> (In-Parameter): Kennung des anfordernden Dcm-Clients.</li>\n<li><code>Dem_DTCRequestType</code> (In-Parameter): Definiert das zeitliche Filterkriterium (First/Most Recent, Failed/Confirmed).</li>\n<li><code>uint32** DTC</code> (Out-Parameter): Zeiger auf den Puffer bzw. Speicherort für den 3-Byte-DTC-Wert (UDS-Format, High-Byte bis Low-Byte).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Das <code>Generic Scan Tool</code> sendet einen Diagnoserequest <code>ReadDTCInformation</code> (Service <code>0x19</code>) mit einer der zeitbasierten Subfunktionen (<code>0x0B</code>–<code>0x0E</code>) an die ECU (über PduR/CanTp/DoIP an den <code>Dcm</code>).</li>\n<li><strong>Synchroner Modulaufruf:</strong> Der <code>Dcm</code> parst die Subfunktion, mappt sie auf den Aufrufparameter <code>Dem_DTCRequestType</code> und ruft synchron die BSW-C-API [<code>Dem_GetDTCByOccurrenceTime</code>](file:///private/tmp/autodocs-worktrees/task-figure-evidence) unter Übergabe der <code>ClientId</code> auf.</li>\n<li><strong>Auswertung im Dem:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>Dem</code> ermittelt im internen Event-Memory anhand der chronologischen Zeitstempel/Reihenfolge den geforderten DTC.</li>\n<li>Der <code>Dem</code> liefert synchron den Rückgabewert (<code>Std_ReturnType</code>) und belegt im Erfolgsfall den Out-Parameter <code>DTC</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Antwortgenerierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Positiver Pfad:</strong> Gibt der <code>Dem</code> <code>E_OK</code> zurück, serialisiert der <code>Dcm</code> die positive Response <code>0x59 &lt;SubFunction&gt; &lt;DTCStatusAvailabilityMask&gt; &lt;DTCAndStatusRecord&gt;</code> und sendet sie an den Tester.</li>\n<li><strong>Negativer Pfad:</strong> Liefert der <code>Dem</code> <code>DEM_OCCURR_NOT_AVAILABLE</code> (oder einen Fehlercode ungleich <code>E_OK</code>) oder schlägt die Validierung fehl, erzeugt der <code>Dcm</code> eine negative Response (NRC, z. B. NRC <code>0x31</code> <em>Request Out Of Range</em> oder NRC <code>0x12</code> <em>SubFunctionNotSupported</em>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsabhängigkeit:</strong></li>\n<li>Das Feature erfordert im <code>Dem</code> die Aktivierung der chronologischen Event-Speicherung (Parameter <code>DemOccurrenceCounterProcessing</code> bzw. chronologisches FIFO/Ringpuffer-Management für Event-Records).</li>\n<li>Im <code>Dcm</code> müssen die Subfunktionen <code>0x0B</code>–<code>0x0E</code> in <code>DcmDspReadDTC</code> explizit konfiguriert und aktiviert sein (<code>DcmDspReadDtcByOccurrenceTimeSupported = TRUE</code>).</li>\n<li><strong>API-Vertrag (Synchronität & Client-Identifikation):</strong></li>\n<li>[<code>Dem_GetDTCByOccurrenceTime</code>](file:///private/tmp/autodocs-worktrees/task-figure-evidence) ist eine <strong>synchrone</strong> API. Der <code>Dem</code> muss die Information direkt ohne Blockieren oder Kontextwechsel aus dem RAM liefern. Eine Verzögerung blockiert die Task des <code>Dcm</code> (<code>Dcm_MainFunction</code>).</li>\n<li>Über den Parameter <code>ClientId</code> (<code>uint8</code>) adressiert der <code>Dcm</code> die dedizierte Client-Instanz im <code>Dem</code>, um parallele Diagnosezugriffe sauber zu trennen.</li>\n<li><strong>Format-Mapping:</strong></li>\n<li>Der Out-Parameter liefert den 24-Bit-DTC in einem <code>uint32</code>. Entwickler müssen sicherstellen, dass das High-Byte im <code>uint32</code> normgerecht auf 0 bzw. das geforderte UDS-Format maskiert ist, bevor der <code>Dcm</code> das PDU-Payload assembliert.</li>\n</ul>"}], "trans": [{"from": "FIG-b4b135ebe3bef338", "to": "FIG-ef0fb62f266adb57", "fr": "R4.1.3", "tr": "R4.2.2", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>API-Aufruf Dem_DcmGetDTCByOccurrenceTime: Parametertyp DTCRequestType um das Modulpräfix zu Dem_DTCRequestType ergänzt.</li>\n</ul>"}, {"from": "FIG-ef0fb62f266adb57", "to": "FIG-a46f9d14591d42b6", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>API-Aufruf Dem_DcmGetDTCByOccurrenceTime: Funktion in Dem_GetDTCByOccurrenceTime umbenannt.</li>\n<li>API-Aufruf Dem_GetDTCByOccurrenceTime: Rückgabetyp von Dem_ReturnGetDTCByOccurrenceTimeType auf Std_ReturnType umgestellt.</li>\n<li>API-Aufruf Dem_GetDTCByOccurrenceTime: Zusätzlicher Parameter uint8 (ClientId) an zweiter Position eingefügt.</li>\n</ul>"}, {"from": "FIG-a46f9d14591d42b6", "to": "FIG-34beeef76e65957d", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>API-Aufruf Dem_GetDTCByOccurrenceTime: Typ des DTC-Ausgabeparameters von uint32<em> auf uint32</em>* geändert.</li>\n</ul>"}, {"from": "FIG-34beeef76e65957d", "to": "FIG-f25e39c21e26fe62", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f25e39c21e26fe62", "to": "FIG-1f7f96e3197b1255", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
